-- Drive Learn - atualização auditada do catálogo de ônibus Scania.
-- Gerado em 2026-09-16; idempotente; preenche lacunas sem substituir dados válidos já cadastrados.
-- Não confundir peso/tara do chassi com PBT. Protótipos e lançamentos futuros ficam inativos.
SET NAMES utf8mb4;
START TRANSACTION;

CREATE TABLE IF NOT EXISTS schema_migrations (versao VARCHAR(80) NOT NULL PRIMARY KEY, descricao VARCHAR(255) NOT NULL, aplicado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS modelo_especificacoes_tecnicas (modelo_id BIGINT UNSIGNED NOT NULL,chave VARCHAR(80) NOT NULL,rotulo VARCHAR(120) NOT NULL,valor VARCHAR(255) NOT NULL,unidade VARCHAR(30) NULL,fonte_url VARCHAR(700) NULL,conferido_em DATE NULL,PRIMARY KEY(modelo_id,chave),INDEX idx_met_chave_029(chave),CONSTRAINT fk_met_modelo_029 FOREIGN KEY(modelo_id) REFERENCES modelos(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;



-- Scania K 320 4x2NB
UPDATE modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id SET m.motor=CASE WHEN m.motor IS NULL OR TRIM(m.motor)='' OR LOWER(TRIM(m.motor)) IN ('não informado','nao informado','n/d') THEN 'Scania 13 l, 6 cilindros, Proconve P8' ELSE m.motor END,m.potencia=CASE WHEN m.potencia IS NULL OR TRIM(m.potencia)='' OR LOWER(TRIM(m.potencia)) IN ('não informado','nao informado','n/d') THEN '320 hp' ELSE m.potencia END,m.torque=CASE WHEN m.torque IS NULL OR TRIM(m.torque)='' OR LOWER(TRIM(m.torque)) IN ('não informado','nao informado','n/d') THEN '1.600 Nm @ 1.050-1.400 rpm' ELSE m.torque END,m.transmissao=CASE WHEN m.transmissao IS NULL OR TRIM(m.transmissao)='' OR LOWER(TRIM(m.transmissao)) IN ('não informado','nao informado','n/d') THEN 'Scania Opticruise GRS/GRSO automatizada, 12 marchas' ELSE m.transmissao END,m.relacao_reducao=CASE WHEN m.relacao_reducao IS NULL OR TRIM(m.relacao_reducao)='' OR LOWER(TRIM(m.relacao_reducao)) IN ('não informado','nao informado','n/d') THEN '2,72:1 / 2,92:1 / 3,08:1' ELSE m.relacao_reducao END,m.descricao=CASE WHEN m.descricao IS NULL OR TRIM(m.descricao)='' OR LOWER(TRIM(m.descricao)) IN ('não informado','nao informado','n/d') THEN 'Especificações atualizadas a partir de fonte oficial pública.' ELSE m.descricao END,m.especificacoes=JSON_MERGE_PATCH('{"tipo_veiculo":"Ônibus","energia":"Diesel","configuracao":"4x2NB","entre_eixos":"3.000","emissoes":"Proconve P8","mercado":"Rodoviário","observacao_peso":"A ficha informa tara/peso do chassi e capacidade dos eixos, mas não declara PBT total; PBT mantido em branco","fonte_oficial":"https://www.scania.com/br/pt/home/products/onibus/chassi-rodoviario/especificacoetecnicas.html","conferido_em":"2026-09-16","documento_auditoria":"/public/assets/documents/modelos/scania-20260915-cms-files-50649-1721933486000023-2024-baw-k320-4x2nb.pdf"}',COALESCE(m.especificacoes,JSON_OBJECT())) WHERE ma.slug='scania' AND (m.slug='scania-k320-4x2nb-onibus' OR LOWER(TRIM(m.nome))=LOWER(TRIM('Scania K 320 4x2NB')));

