INSERT INTO marcas(nome,slug,pais_origem,site_oficial,descricao,ativo) VALUES ('Scania','scania','Suécia','https://www.scania.com/br/pt/home/products/onibus.html','Fabricante de chassis e veículos para transporte de passageiros.',1) ON DUPLICATE KEY UPDATE site_oficial=VALUES(site_oficial),descricao=COALESCE(NULLIF(descricao,''),VALUES(descricao));
INSERT INTO familias(marca_id,nome,descricao,tipo_veiculo,ativo) SELECT id,'Série K Rodoviários','Chassis rodoviários Scania da geração P8 anterior ao powertrain Super.','onibus',1 FROM marcas WHERE slug='scania' ON DUPLICATE KEY UPDATE descricao=COALESCE(NULLIF(familias.descricao,''),VALUES(descricao)),tipo_veiculo='onibus';
