INSERT INTO modelos(familia_id,nome,slug,descricao,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'Scania K 320 4x2NB','scania-k320-4x2nb-onibus','Especificações atualizadas a partir de fonte oficial pública.','Scania 13 l, 6 cilindros, Proconve P8','320 hp','1.600 Nm @ 1.050-1.400 rpm','Scania Opticruise GRS/GRSO automatizada, 12 marchas',NULL,NULL,'2,72:1 / 2,92:1 / 3,08:1','{"tipo_veiculo":"Ônibus","energia":"Diesel","configuracao":"4x2NB","entre_eixos":"3.000","emissoes":"Proconve P8","mercado":"Rodoviário","observacao_peso":"A ficha informa tara/peso do chassi e capacidade dos eixos, mas não declara PBT total; PBT mantido em branco","fonte_oficial":"https://www.scania.com/br/pt/home/products/onibus/chassi-rodoviario/especificacoetecnicas.html","conferido_em":"2026-09-16","documento_auditoria":"/public/assets/documents/modelos/scania-20260915-cms-files-50649-1721933486000023-2024-baw-k320-4x2nb.pdf"}',1 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='scania' AND f.nome='Série K Rodoviários' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='scania' AND (mx.slug='scania-k320-4x2nb-onibus' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('Scania K 320 4x2NB')))) LIMIT 1;
INSERT INTO modelo_especificacoes_tecnicas(modelo_id,chave,rotulo,valor,unidade,fonte_url,conferido_em) SELECT m.id,'relacao_reducao','Relação de redução','2,72:1 / 2,92:1 / 3,08:1',NULL,'https://www.scania.com/br/pt/home/products/onibus/chassi-rodoviario/especificacoetecnicas.html','2026-09-16' FROM modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='scania' AND (m.slug='scania-k320-4x2nb-onibus' OR LOWER(TRIM(m.nome))=LOWER(TRIM('Scania K 320 4x2NB')) ) LIMIT 1 ON DUPLICATE KEY UPDATE rotulo=VALUES(rotulo),valor=CASE WHEN valor IS NULL OR TRIM(valor)='' OR LOWER(TRIM(valor)) IN ('não informado','nao informado','n/d') THEN VALUES(valor) ELSE valor END,fonte_url=CASE WHEN valor IS NULL OR TRIM(valor)='' THEN VALUES(fonte_url) ELSE fonte_url END,conferido_em=CASE WHEN valor IS NULL OR TRIM(valor)='' THEN VALUES(conferido_em) ELSE conferido_em END;
