INSERT INTO modelos(familia_id,nome,slug,descricao,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'Scania K 230E 4x2 LB','scania-k230e-4x2-lb','Especificações atualizadas a partir de fonte oficial pública.','Motor elétrico Scania','230 kW contínuos','2.200 Nm','Automatizada de 2 velocidades',NULL,NULL,NULL,'{"tipo_veiculo":"Ônibus","energia":"100% elétrico","configuracao":"4x2 LB","bateria":"416 ou 520 kWh (4 ou 5 packs)","autonomia":"250-300 km","carregamento":"CCS2 DC até 130 kW","mercado":"Urbano","fonte_oficial":"https://www.scania.com/br/pt/home/products/onibus/chassi-urbano.html","conferido_em":"2026-09-16","documento_auditoria":"/public/assets/documents/modelos/scania-20260915-cms-files-50649-1721934104000023-2024-baw-k230e-b4x2lb.pdf"}',1 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='scania' AND f.nome='Série K Urbanos' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='scania' AND (mx.slug='scania-k230e-4x2-lb' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('Scania K 230E 4x2 LB')))) LIMIT 1;
